<?php
$groups=[
 'Компания и оформление'=>['brand_name'=>'Название компании','phone'=>'Телефон','phone_link'=>'Телефон для ссылки (например, +78129328648)','email'=>'Контактный email','address'=>'Адрес','hours'=>'Режим работы','founded'=>'Год основания','logo'=>'Знак логотипа','favicon'=>'Иконка сайта','theme_accent'=>'Основной цвет','theme_warm'=>'Акцентный цвет','theme_background'=>'Фон'],
