 'Почтовые уведомления'=>['mail_to'=>'Получатель заявок','mail_transport'=>'Способ отправки','mail_from'=>'Адрес отправителя','smtp_host'=>'SMTP-сервер','smtp_port'=>'Порт SMTP','smtp_encryption'=>'Шифрование','smtp_user'=>'Логин SMTP','smtp_password'=>'Пароль SMTP'],
