<form method="post" enctype="multipart/form-data" action="<?= admin_url('settings') ?>"><?= csrf_field() ?><input name="action" type="hidden" value="save_settings">
<?php foreach($groups as $group=>$fields): ?><section class="admin-panel"><h2><?= e($group) ?></h2><?php if($group==='Главная страница'): ?><p class="admin-help">Основной заголовок, вступление и главное изображение редактируются в <a href="<?= e(admin_url('pages',['id'=>1])) ?>">карточке главной страницы</a>. Список популярных товаров задается отметкой «Показывать на главной» в карточках товаров.</p><?php elseif($group==='Почтовые уведомления'): ?><p class="admin-help">Сайт сохраняет заявку независимо от результата доставки уведомления. Для SMTP укажите параметры вашего почтового сервера. Адрес отправителя должен быть разрешен почтовым сервисом. Пустое поле пароля сохраняет текущий пароль.</p><?php endif ?><div class="admin-form-grid">
<?php foreach($fields as $key=>$label):$value=setting($key,match($key){'theme_accent'=>'#1f4e79','theme_warm'=>'#f59e0b','theme_background'=>'#f3f6f9',default=>''}); ?>
<label class="field <?= in_array($key,['address','home_directions_lead','home_popular_lead','home_spec_text','home_about_text','cta_text','footer_text'],true)?'field-wide':'' ?>"><?= e($label) ?>
<?php if(in_array($key,['mail_transport','smtp_encryption'],true)): ?><?php $choices=$key==='mail_transport'?['mail'=>'Почта хостинга (mail)','smtp'=>'SMTP']:['tls'=>'STARTTLS (обычно порт 587)','ssl'=>'SSL/TLS (обычно порт 465)','none'=>'Без шифрования']; ?><select name="<?= e($key) ?>"><?php foreach($choices as $c=>$text): ?><option value="<?= e($c) ?>" <?= $value===$c?'selected':'' ?>><?= e($text) ?></option><?php endforeach ?></select>
<?php elseif(in_array($key,['address','home_directions_lead','home_popular_lead','home_spec_text','home_about_text','cta_text','footer_text'],true)): ?><textarea name="<?= e($key) ?>" rows="3" maxlength="8000"><?= e($value) ?></textarea>
<?php elseif($key==='smtp_password'): ?><input type="password" name="smtp_password" value="" autocomplete="new-password" placeholder="Оставьте пустым, чтобы сохранить текущий">
<?php else: ?><input type="<?= str_starts_with($key,'theme_')?'color':(in_array($key,['email','mail_to','mail_from'],true)?'email':'text') ?>" name="<?= e($key) ?>" value="<?= e($value) ?>" <?= in_array($key,['logo','favicon'],true)?'list="settings-media"':'' ?> maxlength="8000">
<?php if(in_array($key,['logo','favicon'],true)): ?><input type="file" name="<?= e($key) ?>_upload" accept=".png,.jpg,.webp,.ico"><img class="admin-image-preview" src="<?= e(asset($value)) ?>" alt="Текущий файл" width="180" height="100"><?php endif ?>
<?php endif ?></label><?php endforeach ?></div></section><?php endforeach ?>
<section class="admin-panel"><h2>Меню и короткие блоки</h2><div class="admin-form-grid"><label class="field field-wide">Основное меню<textarea name="header_menu" rows="8"><?php foreach(json_value(setting('header_menu')) as $m)echo e($m['label'].' | '.$m['path'])."\n"; ?></textarea><small>Одна ссылка на строку: название | внутренний адрес.</small></label><label class="field">Преимущества в главном блоке<textarea name="home_facts" rows="5"><?= e(implode("\n",json_value(setting('home_facts')))) ?></textarea><small>Один пункт на строку.</small></label><label class="field">Этапы работы<textarea name="home_steps" rows="8"><?php foreach(json_value(setting('home_steps')) as $s)echo e($s['title'].' | '.$s['text'])."\n"; ?></textarea><small>Один этап на строку: название | описание.</small></label><label class="field">Собственная статистика<select name="analytics_enabled"><option value="1" <?= setting('analytics_enabled','1')==='1'?'selected':'' ?>>Включена</option><option value="0" <?= setting('analytics_enabled')==='0'?'selected':'' ?>>Отключена</option></select></label></div></section>
<datalist id="settings-media"><?php foreach(rows('SELECT file_path,original_name FROM media ORDER BY id DESC') as $m): ?><option value="<?= e($m['file_path']) ?>"><?= e($m['original_name']) ?></option><?php endforeach ?></datalist><div class="settings-save"><button class="admin-btn" type="submit">Сохранить настройки</button></div></form>
